{"cmd":"python - <<'PY'
import json, csv
from pathlib import Path

input_path = Path('/root/trivy_report.json')
output_path = Path('/root/security_audit.csv')

with input_path.open('r', encoding='utf-8') as f:
    data = json.load(f)

headers = ["Package","Version","CVE_ID","Severity","CVSS_Score","Fixed_Version","Title","Url"]

def get_cvss_score(vuln):
    cvss = vuln.get('CVSS', {})
    if isinstance(cvss, dict):
        for source in ['nvd','ghsa','redhat']:
            if source in cvss and isinstance(cvss[source], dict):
                score = cvss[source].get('V3Score')
                if isinstance(score, (int, float)):
                    return score
        # fallback to NVD v2 if no v3
        if 'nvd' in cvss and isinstance(cvss['nvd'], dict):
            score = cvss['nvd'].get('V2Score')
            if isinstance(score, (int, float)):
                return score
    return 'N/A'

def get_title(vuln):
    title = vuln.get('Title')
    if title:
        return title
    desc = vuln.get('Description')
    if desc:
        return desc
    return 'N/A'

def get_url(vuln):
    url = vuln.get('PrimaryURL')
    if url:
        return url
    refs = vuln.get('References')
    if isinstance(refs, list) and refs:
        return refs[0]
    return 'N/A'

rows = []
for result in data.get('Results', []):
    for vuln in result.get('Vulnerabilities', []) or []:
        severity = vuln.get('Severity', 'UNKNOWN')
        if severity not in ('HIGH','CRITICAL'):
            continue
        rows.append({
            "Package": vuln.get('PkgName') or 'N/A',
            "Version": vuln.get('InstalledVersion') or 'N/A',
            "CVE_ID": vuln.get('VulnerabilityID') or 'N/A',
            "Severity": severity,
            "CVSS_Score": get_cvss_score(vuln),
            "Fixed_Version": vuln.get('FixedVersion') or 'N/A',
            "Title": get_title(vuln),
            "Url": get_url(vuln),
        })

with output_path.open('w', newline='', encoding='utf-8') as f:
    writer = csv.DictWriter(f, fieldnames=headers)
    writer.writeheader()
    writer.writerows(rows)

print(f"Wrote {len(rows)} rows to {output_path}")
PY"}
